    __global__ void flattenTreesKernel(PtrStepSz<int> comps, const PtrStep<Edges> edges)
    {
      int x = threadIdx.x + blockIdx.x * blockDim.x;
      int y = threadIdx.y + blockIdx.y * blockDim.y;       

