#include "device.hpp"
#include <pcl/gpu/utils/device/warped_compaction.hpp>
//#include <pcl/gpu/utils/device/funcattrib.hpp>
//include <pcl/gpu/utils/device/block.hpp>
//#include <pcl/gpu/utils/device/warp.hpp>

namespace pcl
{
  namespace device
  {

    ////////////////////////////////////////////////////////////////////////////////////////
    ///// Full Volume Scan6

    enum
    {
      CTA_SIZE_X = 32,
      CTA_SIZE_Y = 6,
      CTA_SIZE = CTA_SIZE_X * CTA_SIZE_Y,

      MAX_LOCAL_POINTS = 3
    };



    struct FullScan6
    {
      pcl::device::WarpCompaction compact;
      PtrStep<short2> volume;
      float3 cell_size;

      mutable PtrSz<PointType> output;

      __device__ __forceinline__ float
      fetch (int x, int y, int z, int& weight) const
      {
        float tsdf;
        unpack_tsdf (volume.ptr (VOLUME_Y * z + y)[x], tsdf, weight);
        return tsdf;
      }

      __device__ __forceinline__ void
      operator () () const
      {
        int x = threadIdx.x + blockIdx.x * CTA_SIZE_X;
        int y = threadIdx.y + blockIdx.y * CTA_SIZE_Y;

        if (__all_sync (__activemask (), x >= VOLUME_X)
            || __all_sync (__activemask (), y >= VOLUME_Y))
          return;

        float3 V;
        V.x = (x + 0.5f) * cell_size.x;
        V.y = (y + 0.5f) * cell_size.y;

        int warp_total = 0;

        for (int z = 0; z < VOLUME_Z - 1; ++z)
        {
          float3 points[MAX_LOCAL_POINTS];
          int local_count = 0;

          if (x < VOLUME_X && y < VOLUME_Y)
          {
            int W;
            float F = fetch (x, y, z, W);

            if (W != 0 && F != 1.f)
            {
              V.z = (z + 0.5f) * cell_size.z;

              //process dx
              if (x + 1 < VOLUME_X)
              {
                int Wn;
                float Fn = fetch (x + 1, y, z, Wn);

                if (Wn != 0 && Fn != 1.f)
                  if ((F > 0 && Fn < 0) || (F < 0 && Fn > 0))
                  {
                    float3 p;
                    p.y = V.y;
                    p.z = V.z;

                    float Vnx = V.x + cell_size.x;

                    float d_inv = 1.f / (std::abs (F) + std::abs (Fn));
                    p.x = (V.x * std::abs (Fn) + Vnx * std::abs (F)) * d_inv;

                    points[local_count++] = p;
                  }
              }               /* if (x + 1 < VOLUME_X) */

              //process dy
              if (y + 1 < VOLUME_Y)
              {
                int Wn;
                float Fn = fetch (x, y + 1, z, Wn);

                if (Wn != 0 && Fn != 1.f)
                  if ((F > 0 && Fn < 0) || (F < 0 && Fn > 0))
                  {
                    float3 p;
                    p.x = V.x;
                    p.z = V.z;

                    float Vny = V.y + cell_size.y;

                    float d_inv = 1.f / (std::abs (F) + std::abs (Fn));
                    p.y = (V.y * std::abs (Fn) + Vny * std::abs (F)) * d_inv;

                    points[local_count++] = p;
                  }
              }                /*  if (y + 1 < VOLUME_Y) */

              //process dz
              //if (z + 1 < VOLUME_Z) // guaranteed by loop
              {
                int Wn;
                float Fn = fetch (x, y, z + 1, Wn);

                if (Wn != 0 && Fn != 1.f)
                  if ((F > 0 && Fn < 0) || (F < 0 && Fn > 0))
                  {
                    float3 p;
                    p.x = V.x;
                    p.y = V.y;

                    float Vnz = V.z + cell_size.z;

                    float d_inv = 1.f / (std::abs (F) + std::abs (Fn));
                    p.z = (V.z * std::abs (Fn) + Vnz * std::abs (F)) * d_inv;

                    points[local_count++] = p;
                  }
              }               /* if (z + 1 < VOLUME_Z) */
            }              /* if (W != 0 && F != 1.f) */
          }            /* if (x < VOLUME_X && y < VOLUME_Y) */

          int lane = threadIdx.x;
          int inclusive = local_count;
          #pragma unroll
          for (int delta = 1; delta < 32; delta <<= 1) {
            int previous = __shfl_up_sync(0xffffffff, inclusive, delta);
            if (lane >= delta) inclusive += previous;
          }
          int total_warp = __shfl_sync(0xffffffff, inclusive, 31);
          int offset = inclusive - local_count;
          if (total_warp) {
            int base = compact.reserve(total_warp, warp_total);
            for (int l = 0; l < local_count; ++l) {
              int index = base + offset + l;
              if (index < output.size) {
                auto p = points[l];
                store_point_type(p.x, p.y, p.z, output.data + index);
                compact.record(index, warp_total + offset + l);
              }
            }
            warp_total += total_warp;
          }

        }         /* for(int z = 0; z < VOLUME_Z - 1; ++z) */
          compact.finish(warp_total);


        /////////////////////////
      }       /* operator() */

      __device__ __forceinline__ void
