      }

      __device__ __forceinline__ float3
      fetchPoint (int idx) const
      {
        PointType p = points.data[idx];
        return make_float3 (p.x, p.y, p.z);
      }
      __device__ __forceinline__ void
      storeNormal (int idx, float3 normal) const
        return cubeindex;
      }
    };

    struct VoxelWriter {
      int* indices;
      int* sizes;
      __device__ void operator()(int i, int2 v) const {
        indices[i] = v.x;
        sizes[i] = v.y;
      }
    };

    struct OccupiedVoxels : public CubeIndexEstimator
    {
      enum
      {        
        CTA_SIZE_X = 32,
        CTA_SIZE_Y = 8,
        CTA_SIZE = CTA_SIZE_X * CTA_SIZE_Y,

        WARPS_COUNT = CTA_SIZE / Warp::WARP_SIZE
      };

      pcl::device::WarpCompaction compact;
      int2* staging;
      mutable int* voxels_indeces;
      mutable int* vetexes_number;
      int max_size;

      __device__ __forceinline__ void
      operator () () const
      {
        int x = threadIdx.x + blockIdx.x * CTA_SIZE_X;
        int y = threadIdx.y + blockIdx.y * CTA_SIZE_Y;

        if (__all_sync (__activemask (), x >= VOLUME_X)
            || __all_sync (__activemask (), y >= VOLUME_Y))
          return;


        int warp_total = 0;

        for (int z = 0; z < VOLUME_Z - 1; z++)
        {
          int numVerts = 0;
          if (x + 1 < VOLUME_X && y + 1 < VOLUME_Y)
          {
            float field[8];
            int cubeindex = computeCubeIndex (x, y, z, field);

            // read number of vertices from texture
            numVerts = (cubeindex == 0 || cubeindex == 255) ? 0 : numVertsTex[cubeindex];
          }

          int total = __popc (__ballot_sync (__activemask (), numVerts > 0));
		  if (total == 0)
			continue;

          int base = compact.reserve(total, warp_total);
          int offs = Warp::binaryExclScan(__ballot_sync(0xffffffff, numVerts > 0));
          int index = base + offs;
          if (numVerts > 0 && index < max_size) {
            int voxel = VOLUME_Y * VOLUME_X * z + VOLUME_X * y + x;
            if (compact.direct) {
              voxels_indeces[index] = voxel;
              vetexes_number[index] = numVerts;
            } else {
              staging[index] = make_int2(voxel, numVerts);
              compact.record(index, warp_total + offs);
            }
          }
          warp_total += total;


        } /* for(int z = 0; z < VOLUME_Z - 1; z++) */


compact.finish(warp_total);
      } /* operator () */
    };
    __global__ void getOccupiedVoxelsKernel (const OccupiedVoxels ov) { ov (); }
  }
}

int
pcl::device::getOccupiedVoxels (DeviceArray<unsigned char>& scratch_buffer, const int* numVerts, const PtrStep<short2>& volume, DeviceArray2D<int>& occupied_voxels)
{
  pcl::device::WarpedCompaction<int2> scratch(scratch_buffer, occupied_voxels.cols(),
      divUp(VOLUME_X, OccupiedVoxels::CTA_SIZE_X) * divUp(VOLUME_Y, OccupiedVoxels::CTA_SIZE_Y) * OccupiedVoxels::CTA_SIZE_Y);
  OccupiedVoxels ov;
  ov.compact = scratch.device;
  ov.staging = scratch.values;
  ov.numVertsTex = numVerts;
  ov.volume = volume;

  ov.voxels_indeces = occupied_voxels.ptr (0);
  ov.vetexes_number = occupied_voxels.ptr (1);
  ov.max_size = occupied_voxels.cols ();

  dim3 block (OccupiedVoxels::CTA_SIZE_X, OccupiedVoxels::CTA_SIZE_Y);
  dim3 grid (divUp (VOLUME_X, block.x), divUp (VOLUME_Y, block.y));

  //cudaFuncSetCacheConfig(getOccupiedVoxelsKernel, cudaFuncCachePreferL1);
  //printFuncAttrib(getOccupiedVoxelsKernel);

  getOccupiedVoxelsKernel<<<grid, block>>>(ov);
  cudaSafeCall ( cudaGetLastError () );
  cudaSafeCall (cudaDeviceSynchronize ());

  int size = scratch.scan();
  if (size <= ov.max_size) {
    scratch.scatter(size, VoxelWriter{ov.voxels_indeces, ov.vetexes_number});
  } else {
    ov.compact.direct = true;
    getOccupiedVoxelsKernel<<<grid, block>>>(ov);
    size = ov.max_size;
  }
  cudaSafeCall(cudaGetLastError());
  cudaSafeCall(cudaDeviceSynchronize());
  return size;
}

int
pcl::device::computeOffsetsAndTotalVertexes (DeviceArray2D<int>& occupied_voxels)
{
  thrust::device_ptr<int> beg (occupied_voxels.ptr (1));
  thrust::device_ptr<int> end = beg + occupied_voxels.cols ();

  thrust::device_ptr<int> out (occupied_voxels.ptr (2));
  thrust::exclusive_scan (beg, end, out);

  int lastElement, lastScanElement;

  DeviceArray<int> last_elem (occupied_voxels.ptr(1) + occupied_voxels.cols () - 1, 1);
  DeviceArray<int> last_scan (occupied_voxels.ptr(2) + occupied_voxels.cols () - 1, 1);

  last_elem.download (&lastElement);
  last_scan.download (&lastScanElement);

  return lastElement + lastScanElement;
}


